using Marina.Application.Commerce; using Marina.Domain.Catalog; using Marina.Domain.Commerce; using Xunit;
namespace Marina.UnitTests;
public sealed class CheckoutServiceTests{
 [Fact]public async Task Checkout_recalculates_totals_and_deducts_inventory(){var f=Fixture();var service=new CheckoutService(f);var order=await service.CreateAsync(new CheckoutCommand(f.UserId,f.Address.Id,"key-1",[new CheckoutLine(f.Variant.Id,2)],null),default);Assert.Equal(200m,order.Subtotal);Assert.Equal(20m,order.Shipping);Assert.Equal(33m,order.Tax);Assert.Equal(253m,order.Total);Assert.Equal(3,f.Variant.Inventory.Quantity);Assert.Contains(f.Added.OfType<StockMovement>(),x=>x.Delta==-2&&x.NewQuantity==3);}
 [Fact]public async Task Checkout_rejects_insufficient_inventory(){var f=Fixture();var service=new CheckoutService(f);await Assert.ThrowsAsync<InvalidOperationException>(()=>service.CreateAsync(new CheckoutCommand(f.UserId,f.Address.Id,"key-2",[new CheckoutLine(f.Variant.Id,6)],null),default));Assert.Equal(5,f.Variant.Inventory.Quantity);}
 [Fact]public async Task Checkout_is_idempotent(){var f=Fixture();var service=new CheckoutService(f);var command=new CheckoutCommand(f.UserId,f.Address.Id,"same-key",[new CheckoutLine(f.Variant.Id,1)],null);var first=await service.CreateAsync(command,default);f.Existing=first;var second=await service.CreateAsync(command,default);Assert.Same(first,second);Assert.Equal(4,f.Variant.Inventory.Quantity);}
 [Fact]public async Task Checkout_rejects_duplicate_variant_lines(){var f=Fixture();var service=new CheckoutService(f);await Assert.ThrowsAsync<ArgumentException>(()=>service.CreateAsync(new CheckoutCommand(f.UserId,f.Address.Id,"key-3",[new CheckoutLine(f.Variant.Id,1),new CheckoutLine(f.Variant.Id,1)],null),default));}
 private static FakeRepository Fixture(){var user=Guid.NewGuid();var address=new Address{UserId=user,Recipient="Sarah",Phone="0500000000",City="Riyadh",Line1="Olaya"};var product=new Product{IsActive=true,Translations=[new ProductTranslation{Culture="en",Name="Dress"}]};var variant=new ProductVariant{Product=product,Sku="MAR-DR-1",Price=100,IsActive=true,Inventory=new Inventory{Quantity=5}};return new FakeRepository(user,address,variant);}
 private sealed class FakeRepository(Guid userId,Address address,ProductVariant variant):ICommerceRepository{public Guid UserId{get;}=userId;public Address Address{get;}=address;public ProductVariant Variant{get;}=variant;public Order?Existing{get;set;}public List<object>Added{get;}=[];public Task<Order?>FindOrderByIdempotencyAsync(Guid userId,string key,CancellationToken ct)=>Task.FromResult(Existing?.IdempotencyKey==key?Existing:null);public Task<Address?>FindOwnedAddressAsync(Guid userId,Guid id,CancellationToken ct)=>Task.FromResult<Address?>(userId==UserId&&id==Address.Id?Address:null);public Task<IReadOnlyDictionary<Guid,ProductVariant>>GetVariantsForCheckoutAsync(IEnumerable<Guid>ids,CancellationToken ct)=>Task.FromResult<IReadOnlyDictionary<Guid,ProductVariant>>(new Dictionary<Guid,ProductVariant>{{Variant.Id,Variant}});public Task<Coupon?>FindCouponAsync(string code,CancellationToken ct)=>Task.FromResult<Coupon?>(null);public Task<int>CouponUseCountAsync(Guid couponId,Guid?userId,CancellationToken ct)=>Task.FromResult(0);public Task<T>InSerializableTransactionAsync<T>(Func<CancellationToken,Task<T>>operation,CancellationToken ct)=>operation(ct);public Task ClearPurchasedCartAsync(Guid userId,IEnumerable<Guid> variantIds,CancellationToken ct)=>Task.CompletedTask;public void Add<T>(T entity)where T:class=>Added.Add(entity);public Task SaveAsync(CancellationToken ct)=>Task.CompletedTask;}
}
